def choose_move(observation):
    def p(v, d=None):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return d

    def add_points(container, key):
        for a in observation.get(key, []):
            q = p(a)
            if q is not None:
                container.append(q)

    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0
    sx, sy = p(observation.get("self_position", (0, 0)), (0, 0))
    ox, oy = p(observation.get("opponent_position", (sx, sy)), (sx, sy))

    obs = set()
    for k in ("obstacles", "walls", "blocked", "hazards"):
        for a in observation.get(k, []):
            q = p(a)
            if q is not None:
                obs.add(q)

    targets = []
    for k in ("resources", "resource_positions", "goals", "goal_positions",
              "capture_points", "control_points", "objectives", "territory_points",
              "anchors", "items"):
        add_points(targets, k)

    if not targets:
        for k in ("self_path", "path", "trail", "territory", "territory_cells"):
            add_points(targets, k)

    if not targets:
        tx, ty = p(observation.get("target_position"), None)
        if tx is not None:
            targets.append((tx, ty))

    # Candidate moves
    moves = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]

    # Determine whether to pressure opponent or avoid them
    d_op = abs(sx - ox) + abs(sy - oy)
    d_tgt = 10**9
    best_tgt = None
    for tx, ty in targets:
        d = abs(tx - sx) + abs(ty - sy)
        if d < d_tgt or (d == d_tgt and (best_tgt is None or (tx, ty) < best_tgt)):
            d_tgt = d
            best_tgt = (tx, ty)

    best_move = (0, 0)
    best_score = -10**18

    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if nx < 0 or ny < 0 or (w and nx >= w) or (h and ny >= h):
            continue
        if (nx, ny) in obs:
            continue

        score = 0

        # Prefer progress toward targets when present.
        if best_tgt is not None:
            nd = abs(best_tgt[0] - nx) + abs(best_tgt[1] - ny)
            score += (20 - nd) * 10
            if (nx, ny) == best_tgt:
                score += 200

        # In contest situations, bias away from nearby opponent unless we can close on target.
        nd_op = abs(nx - ox) + abs(ny - oy)
        if d_op <= 2:
            score += nd_op * 12
        else:
            score += nd_op * 2

        # Mild centrality to reduce edge trapping.
        if w and h:
            cx, cy = (w - 1) // 2, (h - 1) // 2
            score -= (abs(nx - cx) + abs(ny - cy))

        # Small preference for motion over idling if tied.
        if dx or dy:
            score += 1

        if score > best_score or (score == best_score and (dx, dy) < best_move):
            best_score = score
            best_move = (dx, dy)

    return [best_move[0], best_move[1]]

